-- CANONICAL SOURCE: shared/ui/Sparkline.lua. Staged copies under addons/*/*/Shared/UI/ are
-- generated by scripts/sync-shared.sh - never edit them; edit this file and re-sync.
--[[
    shared/ui/Sparkline.lua - Tiny line + area chart from recorded samples.

    No axes, no labels. Straight segments join consecutive recorded samples only;
    nothing is smoothed or invented. The scale always starts at zero, so a quiet
    session draws flat at the bottom. Lines and fill columns are pooled and reused,
    so a redraw never creates frames once the pool has grown to maxPoints.
]]

local _, addon = ...

addon.UI = addon.UI or {}
addon.UI.Sparkline = addon.UI.Sparkline or {}
local Sparkline = addon.UI.Sparkline
local PHUI = addon.UI.PHUI

local DEFAULT_MAX_POINTS = 48
local FILL_ALPHA = 0.28
local LINE_THICKNESS = 1.5

-- Reduce `values` (oldest first) to at most `maxPoints` by bucket average.
-- Returns a new array; the input is never modified.
function Sparkline.Downsample(values, maxPoints)
    local n = #values
    if n <= maxPoints then
        local copy = {}
        for i = 1, n do copy[i] = values[i] end
        return copy
    end
    local out = {}
    for i = 1, maxPoints do
        local from = math.floor((i - 1) * n / maxPoints) + 1
        local to = math.floor(i * n / maxPoints)
        if to < from then to = from end
        local sum = 0
        for j = from, to do sum = sum + values[j] end
        out[i] = sum / (to - from + 1)
    end
    return out
end

-- opts: width, height (required), color {r,g,b[,a]} (default accent gold),
-- maxPoints (default 48), fill (default true)
function Sparkline:Create(parent, opts)
    opts = opts or {}
    local color = opts.color or PHUI.Colors.ACCENT_GOLD
    local frame = CreateFrame("Frame", nil, parent)
    frame:SetSize(opts.width, opts.height)

    frame.color = color
    frame.maxPoints = opts.maxPoints or DEFAULT_MAX_POINTS
    frame.fill = opts.fill ~= false
    frame.lines = {}
    frame.columns = {}

    function frame:SetColor(c)
        self.color = c
    end

    local function hideFrom(pool, first)
        for i = first, #pool do pool[i]:Hide() end
    end

    function frame:Clear()
        hideFrom(self.lines, 1)
        hideFrom(self.columns, 1)
    end

    -- values: array of numbers, oldest first. Fewer than 2 samples draws a flat
    -- baseline (we have no trend to show, and don't pretend to).
    function frame:SetValues(values)
        local w, h = self:GetWidth(), self:GetHeight()
        if not w or w <= 0 then w = opts.width end
        if not h or h <= 0 then h = opts.height end
        local c = self.color
        local pts = Sparkline.Downsample(values or {}, self.maxPoints)
        local n = #pts

        if n < 2 then
            self:Clear()
            local line = self.lines[1]
            if not line then
                line = self:CreateLine(nil, "ARTWORK")
                self.lines[1] = line
            end
            line:SetThickness(LINE_THICKNESS)
            line:SetColorTexture(c[1], c[2], c[3], 0.5)
            line:SetStartPoint("BOTTOMLEFT", self, 0, 1)
            line:SetEndPoint("BOTTOMRIGHT", self, 0, 1)
            line:Show()
            return
        end

        local max = 0
        for i = 1, n do
            if pts[i] > max then max = pts[i] end
        end
        local step = w / (n - 1)
        local function yOf(v)
            if max <= 0 then return 1 end
            return 1 + (v / max) * (h - 2)
        end

        for i = 1, n - 1 do
            local line = self.lines[i]
            if not line then
                line = self:CreateLine(nil, "ARTWORK")
                self.lines[i] = line
            end
            line:SetThickness(LINE_THICKNESS)
            line:SetColorTexture(c[1], c[2], c[3], c[4] or 1)
            line:SetStartPoint("BOTTOMLEFT", self, (i - 1) * step, yOf(pts[i]))
            line:SetEndPoint("BOTTOMLEFT", self, i * step, yOf(pts[i + 1]))
            line:Show()
        end
        hideFrom(self.lines, n)

        if self.fill then
            -- One column per segment at the segment's lower sample: the shaded area
            -- never rises above the drawn line.
            for i = 1, n - 1 do
                local col = self.columns[i]
                if not col then
                    col = self:CreateTexture(nil, "BACKGROUND")
                    self.columns[i] = col
                end
                local top = math.min(yOf(pts[i]), yOf(pts[i + 1]))
                col:SetColorTexture(c[1], c[2], c[3], FILL_ALPHA)
                col:ClearAllPoints()
                col:SetPoint("BOTTOMLEFT", self, "BOTTOMLEFT", (i - 1) * step, 0)
                col:SetSize(math.max(1, step), math.max(1, top))
                col:Show()
            end
            hideFrom(self.columns, n)
        else
            hideFrom(self.columns, 1)
        end
    end

    frame:SetValues({})
    return frame
end
